import{_ as r,o as a,c as t,ae as n}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Azure: hierarchy, audiences, and access","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1917971986/references/azure.md","filePath":"adrs/1917971986/references/azure.md"}'),o={name:"adrs/1917971986/references/azure.md"};function s(i,e,c,l,u,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="azure-hierarchy-audiences-and-access" tabindex="-1">Azure: hierarchy, audiences, and access <a class="header-anchor" href="#azure-hierarchy-audiences-and-access" aria-label="Permalink to &quot;Azure: hierarchy, audiences, and access&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-10.</p><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><p>Every Azure subscription trusts exactly one Microsoft Entra tenant, the directory that holds identities and authorizes sign in, while one tenant can be trusted by many subscriptions (<a href="https://learn.microsoft.com/en-us/entra/fundamentals/how-subscriptions-associated-directory" target="_blank" rel="noreferrer">Add an existing Azure subscription to your tenant</a>).</p><p>Above subscriptions sits a management group hierarchy. Each directory has a single root management group, whose ID matches the Microsoft Entra tenant ID, and all management groups and subscriptions in the directory fold up into it. A management group tree supports up to six levels of depth, a limit that does not include the root level or the subscription level, and a single directory can hold up to 10,000 management groups. Each management group or subscription has exactly one parent, though a management group can have many children (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><p>Below a subscription, Azure role-based access control recognizes four scope levels in a parent-child chain: management group, subscription, resource group, and resource (<a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/overview" target="_blank" rel="noreferrer">What is Azure role-based access control (RBAC)?</a>).</p><h2 id="governance-and-work" tabindex="-1">Governance and work <a class="header-anchor" href="#governance-and-work" aria-label="Permalink to &quot;Governance and work&quot;">​</a></h2><p>The Microsoft Entra tenant supplies identity for sign in, while the subscription is the scope where Azure resources and role assignments are managed; changing a subscription&#39;s tenant changes who can sign in to manage it, but never makes the subscription owner a Global Administrator of that tenant (<a href="https://learn.microsoft.com/en-us/entra/fundamentals/how-subscriptions-associated-directory" target="_blank" rel="noreferrer">Add an existing Azure subscription to your tenant</a>).</p><p>Billing runs through a separate hierarchy from the resource tree. A billing account is created when a customer signs up to use Azure, and its shape depends on the agreement type: a Microsoft Online Services Program account contains subscriptions directly, an Enterprise Agreement account contains departments and accounts, a Microsoft Customer Agreement account contains billing profiles and invoice sections, and a Microsoft Partner Agreement account contains billing profiles and customers. A subscription can appear under a billing account and, independently, under a management group in the resource hierarchy, because the two hierarchies track different concerns (<a href="https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/view-all-accounts" target="_blank" rel="noreferrer">View your billing accounts in the Azure portal</a>).</p><p>Policy and access assigned at the root management group apply to the entire directory, to every management group, subscription, resource group, and resource within it, and a resource or subscription owner cannot override that assignment (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><h2 id="audiences-and-visibility" tabindex="-1">Audiences and visibility <a class="header-anchor" href="#audiences-and-visibility" aria-label="Permalink to &quot;Audiences and visibility&quot;">​</a></h2><p>Azure&#39;s primary documentation does not describe a general audience model for resources comparable to public, organization-wide, or invited-member visibility. Not documented.</p><p>Discovery is close to binary rather than audience based. Azure Resource Graph, which backs the portal&#39;s resource search, returns results only for subscriptions the calling principal already has read access to, and returns no results, or a 403, when no such access exists (<a href="https://learn.microsoft.com/en-us/azure/governance/resource-graph/overview" target="_blank" rel="noreferrer">Overview of Azure Resource Graph</a>).</p><p>One documented exception sits at the very top: all Azure customers can see the root management group and where their own subscription sits within the hierarchy, even though only an elevated Global Administrator can manage the root itself (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><h2 id="narrowing-below-a-parent" tabindex="-1">Narrowing below a parent <a class="header-anchor" href="#narrowing-below-a-parent" aria-label="Permalink to &quot;Narrowing below a parent&quot;">​</a></h2><p>Azure RBAC itself is additive: effective permissions are the sum of a principal&#39;s role assignments at every scope in the chain, with no customer-facing mechanism to subtract access at a lower scope (<a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/overview" target="_blank" rel="noreferrer">What is Azure role-based access control (RBAC)?</a>). Deny assignments can block access regardless of a role assignment, but customers cannot create their own deny assignments directly; Azure creates and manages them, for example through deployment stacks, and customer-managed deny assignments are documented as being in private preview only (<a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/deny-assignments" target="_blank" rel="noreferrer">List Azure deny assignments</a>).</p><p>Azure Policy offers an explicit narrowing mechanism instead: a policy exemption, created as a child object on a resource hierarchy or individual resource, excuses that scope from an assignment that would otherwise evaluate it. Exemptions can be time bound through an <code>expiresOn</code> property. Because of the impact of granting one, creating an exemption requires both the <code>Microsoft.Authorization/policyExemptions/write</code> permission on the target scope and the <code>exempt/Action</code> verb on the policy assignment being exempted, so a lower scope cannot narrow itself without a grant tied to the parent assignment (<a href="https://learn.microsoft.com/en-us/azure/governance/policy/concepts/scope" target="_blank" rel="noreferrer">Understand scope in Azure Policy</a>).</p><h2 id="ceilings-from-above" tabindex="-1">Ceilings from above <a class="header-anchor" href="#ceilings-from-above" aria-label="Permalink to &quot;Ceilings from above&quot;">​</a></h2><p>A policy or role assignment made at the root management group reaches every management group, subscription, resource group, and resource in the directory, and the resource or subscription owner cannot alter it (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><p>When several policy assignments with a deny effect apply to the same resource at different scopes, Azure documents the outcome as cumulative and most restrictive: a resource must satisfy every deny policy in its path, and any one of them can block it (<a href="https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effect-basics" target="_blank" rel="noreferrer">Azure Policy definitions effect basics</a>).</p><p>Ceilings at the root are opt-in rather than automatic. No principal has default access to the root management group; a Microsoft Entra Global Administrator must first elevate their own access before they can assign roles or policy there, and only after that elevation does anything apply at the directory-wide ceiling (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><h2 id="discovery-versus-access" tabindex="-1">Discovery versus access <a class="header-anchor" href="#discovery-versus-access" aria-label="Permalink to &quot;Discovery versus access&quot;">​</a></h2><p>Azure&#39;s resource-facing tools largely collapse discovery into access. Azure Resource Graph requires at least read permission on a resource or object group before it returns anything for that scope, with no documented mode that reveals existence without read access (<a href="https://learn.microsoft.com/en-us/azure/governance/resource-graph/overview" target="_blank" rel="noreferrer">Overview of Azure Resource Graph</a>).</p><p>The one documented departure is the root management group, which every Azure customer can see and locate their own subscription within, independent of whether they can manage that root (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>).</p><h2 id="small-customers" tabindex="-1">Small customers <a class="header-anchor" href="#small-customers" aria-label="Permalink to &quot;Small customers&quot;">​</a></h2><p>A billing account is created automatically the moment a customer signs up for Azure, for example through an Azure Free Account or a pay-as-you-go offer, without any separate enrollment step; a new Microsoft Online Services Program billing account of this kind supports up to five subscriptions by default (<a href="https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/view-all-accounts" target="_blank" rel="noreferrer">View your billing accounts in the Azure portal</a>).</p><p>New subscriptions default automatically to the root management group when they are created, so a small customer accumulates subscriptions under the root without ever having to create a management group (<a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a>). Whether such a customer is shown an organization-level concept at all during signup is not documented.</p><h2 id="consolidation" tabindex="-1">Consolidation <a class="header-anchor" href="#consolidation" aria-label="Permalink to &quot;Consolidation&quot;">​</a></h2><p>Azure&#39;s own guidance frames consolidating two Microsoft Entra tenants into one as the typical goal after a merger or acquisition, but also as complex enough that organizations sometimes leave the tenants separate for an extended period rather than complete it. A custom domain name can only belong to one tenant at a time, which is the stated reason consolidation is preferred when it is feasible (<a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/landing-zone/design-area/multi-tenant/scenarios" target="_blank" rel="noreferrer">Scenarios for multiple Microsoft Entra tenants</a>).</p><p>The documented mechanism for moving a unit of work between tenants operates at the subscription level, not the tenant level: a subscription can be transferred to a different Microsoft Entra directory, but role assignments and custom roles are permanently deleted from the source directory, and Azure Policy objects, including definitions, assignments, and exemptions, do not transfer and must be exported, reimported, and reassigned in the target directory (<a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/transfer-subscription" target="_blank" rel="noreferrer">Transfer an Azure subscription to a different Microsoft Entra directory</a>). No primary documentation describes a way to merge two tenants directly; consolidation is a sequence of workload migrations rather than a single operation.</p><h2 id="relevance-to-this-adr" tabindex="-1">Relevance to this ADR <a class="header-anchor" href="#relevance-to-this-adr" aria-label="Permalink to &quot;Relevance to this ADR&quot;">​</a></h2><ul><li>Azure&#39;s root management group matches the ADR&#39;s organization: a single root per tenant that carries identity, and whose policy and role assignments cascade to every workspace-like and folder-like node beneath it, with descendants unable to override what the root sets.</li><li>Azure diverges from the ADR&#39;s strict two-tier split of workspace as a typed child of the root and folder as anything deeper. Management groups and subscriptions nest freely up to six levels with no distinct word or rule marking the first level down from the root, and nothing in Azure corresponds to the ADR&#39;s project as a resource, rather than a position, attached below a workspace or folder.</li><li>The ADR&#39;s rule that root ceilings are opt-in per policy matches Azure closely: no principal has default access to the root management group, and an administrator must elevate access before anything enforced there becomes a ceiling for the rest of the directory.</li><li>Azure&#39;s narrowing mechanism, the policy exemption, diverges from the ADR&#39;s model of any level freely narrowing itself. An exemption requires a permission tied to the parent assignment being exempted, so narrowing in Azure is closer to a grant issued from above than to an independent choice made by the descendant.</li><li>Azure mostly collapses the ADR&#39;s discover and read capabilities into one: Resource Graph and similar tools reveal a resource only to principals who already have read access to it, with the root management group as the sole documented case of existence being visible without management access. Azure&#39;s documented absence of a tenant merge tool, requiring workload-by-workload migration instead, matches the ADR&#39;s position that separately created organizations consolidate only through an explicit migration.</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/azure/governance/management-groups/overview" target="_blank" rel="noreferrer">Organize your resources with management groups</a></li><li><a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/overview" target="_blank" rel="noreferrer">What is Azure role-based access control (RBAC)?</a></li><li><a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/deny-assignments" target="_blank" rel="noreferrer">List Azure deny assignments</a></li><li><a href="https://learn.microsoft.com/en-us/azure/governance/policy/concepts/scope" target="_blank" rel="noreferrer">Understand scope in Azure Policy</a></li><li><a href="https://learn.microsoft.com/en-us/azure/governance/policy/concepts/effect-basics" target="_blank" rel="noreferrer">Azure Policy definitions effect basics</a></li><li><a href="https://learn.microsoft.com/en-us/azure/cost-management-billing/manage/view-all-accounts" target="_blank" rel="noreferrer">View your billing accounts in the Azure portal</a></li><li><a href="https://learn.microsoft.com/en-us/azure/role-based-access-control/transfer-subscription" target="_blank" rel="noreferrer">Transfer an Azure subscription to a different Microsoft Entra directory</a></li><li><a href="https://learn.microsoft.com/en-us/entra/fundamentals/how-subscriptions-associated-directory" target="_blank" rel="noreferrer">Add an existing Azure subscription to your tenant</a></li><li><a href="https://learn.microsoft.com/en-us/azure/governance/resource-graph/overview" target="_blank" rel="noreferrer">Overview of Azure Resource Graph</a></li><li><a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/landing-zone/design-area/multi-tenant/scenarios" target="_blank" rel="noreferrer">Scenarios for multiple Microsoft Entra tenants</a></li></ul>',34)])])}const p=r(o,[["render",s]]);export{m as __pageData,p as default};
